function run(){
  // Grid search over x, y in steps of 0.01 (z is determined).
  let best = 0;
  for (let i = 0; i <= 1200; i++) for (let j = 0; i + j <= 1200; j++) {
    const x = i / 100, y = j / 100, z = (1200 - i - j) / 100;
    best = Math.max(best, x * y * z);
  }
  return best;
}
